(function(){'use strict';
let info=null;
const F=THFinanceCore;
const check=(key,label)=>`<label class="ready-check"><input type="checkbox" data-ready-check="${key}" ${info.reviewed[key]?.confirmed?'checked':''}><span>${label}<small class="muted"> · konfirmasi manual Owner</small></span></label>`;
function card(title,done,text,action=''){return `<article class="ready-card">${badge(done?'Sudah terpenuhi':'Perlu disiapkan',done?'green':'yellow')}<h3>${title}</h3><p>${text}</p>${action}</article>`;}
function body(){const s=THCloud.state,f=s.finance,ops=s.operations,p=f.policies,employees=ops.employees.filter(e=>e.active),reviewers=info.members.filter(m=>m.status==='Aktif'&&['Owner','Finance'].includes(m.role)),config=ops.settings.configured&&ops.settings.packages.length>0;
const checks=[!!employees.length,!!config,!!p.approved,!!p.openingApproved,reviewers.length>=2,...['bankSetup','backupRestore','deviceTrial','sopEvidence'].map(k=>!!info.reviewed[k]?.confirmed)];const done=checks.filter(Boolean).length;
return `<section class="ready-hero"><div><span class="eyebrow">PERSIAPAN TOP HILLS</span><h2>${done===checks.length?'Persiapan terkonfirmasi.':'Siapkan fondasi sebelum mulai.'}</h2><p>${done} dari ${checks.length} pemeriksaan terpenuhi. Infrastruktur tersedia; kesiapan usaha mengikuti pengaturan dan hasil uji Anda.</p><div class="ready-progress"><i style="width:${done/checks.length*100}%"></i></div></div></section>
<div class="ready-provider"><div><strong>Database bersama · ${esc(info.database)}</strong><small>Tersambung · revisi ${s.revision}. Order, jurnal, dan akun tersimpan di server.</small></div><div><strong>File bukti · ${esc(info.proofStorage)}</strong><small>Penyimpanan tersedia. File diakses melalui pemeriksaan akun.</small></div><div><strong>Supabase</strong><small>${info.supabaseConnected?'Tersambung. Akun, order, jurnal, dan bukti menggunakan Supabase.':'Peralihan database belum diaktifkan.'}</small></div></div>
${info.reset?`<p class="notice blue">${icon('check')}Reset data usaha selesai ${esc(new Date(info.reset.completedAt||info.reset.resetAt).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}))} WIB. Akun login dipertahankan.</p>`:''}
<div class="ready-grid">
${card('01 · Tim dan penugasan',employees.length>0,`${employees.length} karyawan aktif. Tambahkan profil karyawan, lalu tautkan ke akun Operator. Akun Konsumen perlu profil penghuni yang tepat.`,btn('Buka tim','ready-team','','btn small'))}
${card('02 · Paket dan aturan kas',config,'Tetapkan harga paket, target selesai, float, batas uang tunai, serta rentang label dan kuitansi.',btn('Atur operasional','settings','','btn small'))}
${card('03 · Kebijakan laporan',p.approved,'Sahkan kebijakan pengakuan pendapatan, unit usaha, dan zona waktu. Jurnal aktivitas memakai WIB.',btn('Buka kebijakan','ready-policies','','btn small'))}
${card('04 · Saldo awal',p.openingApproved,'Lengkapi dan sahkan saldo awal aset, kewajiban, serta ekuitas. Neraca kosong bukan bukti tidak adanya saldo awal.','<button type="button" class="btn small" data-fin="new" data-id="opening">Isi saldo awal</button>')}
${card('05 · Pemeriksa yang berbeda',reviewers.length>=2,`${reviewers.length} akun Owner/Finance aktif. Laporan Final dan rekonsiliasi membutuhkan pemeriksa berbeda dari pencatat. Untuk tim: beri akses situs, minta masuk, lalu tetapkan perannya.`,btn('Kelola akun','ready-members','','btn small'))}
${card('06 · Rekening dan bukti bank',info.reviewed.bankSetup?.confirmed,'Tetapkan rekening usaha dan petugas pencocokan bukti. Pencatatan ini tidak memproses pembayaran atau otomatis menarik mutasi bank.',check('bankSetup','Rekening, cara impor mutasi, dan petugas sudah diperiksa'))}
${card('07 · Cadangan dan pemulihan',info.reviewed.backupRestore?.confirmed,'Unduh cadangan rutin. JSON memuat data serta metadata; byte lampiran perlu dicadangkan terpisah. Pemulihan penuh harus diuji sebelum menyimpan data penting.',btn('Unduh cadangan','backup','','btn small')+check('backupRestore','Saya telah menguji pemulihan data dan file bukti'))}
${card('08 · Uji beberapa perangkat',info.reviewed.deviceTrial?.confirmed,'Masuk di dua perangkat, periksa satu alur terkontrol, lalu periksa sinkronisasi, konflik penyimpanan, dan akun yang dinonaktifkan.',check('deviceTrial','Uji dua perangkat dan pembatasan akses sudah lulus'))}
${card('09 · Kesiapan bukti operasional',info.reviewed.sopEvidence?.confirmed,'Bukti transaksi mendukung unggah file. Meja laundry menyimpan foto timbang dan bukti serah terima yang dapat ditelusuri. Periksa kamera dan perangkat tim sebelum operasional.',check('sopEvidence','Prosedur bukti laundry dan uji SOP telah diverifikasi'))}
</div>
<div class="ready-alert"><strong>Batas kesiapan saat ini.</strong> Tanda “terpenuhi” mencakup konfigurasi sistem dan konfirmasi manual Owner, bukan sertifikasi keamanan. Draft otomatis dibuat saat ruang kerja dibuka; penjadwalan yang berjalan ketika situs tidak dibuka belum aktif.</div>
<h3>Data dan akun usaha</h3><p class="ready-security">${info.supabaseConnected?'Data usaha tersimpan di Supabase dan file bukti bersifat privat.':'Database website masih menunggu peralihan ke Supabase.'} Akun yang sudah ada tetap dipertahankan. Pengguna yang mendaftar lewat email perlu persetujuan Owner sebelum membuka data usaha.</p>
<h3>Akses yang lebih aman</h3><p class="ready-security">Setiap orang menggunakan akun sendiri. Peran dan kepemilikan bukti diperiksa di server; akun yang dicabut tidak dapat membaca atau menyimpan lagi. Data disegarkan setiap 15 detik saat halaman aktif, dan saat kembali online. Formulir yang sedang diisi tidak ditimpa. Aktifkan MFA pada akun ChatGPT dan keluar dari perangkat bersama.</p><p class="ready-footer">Status ditinjau ${new Date().toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})} WIB. Pemeriksaan dua perangkat dan pemulihan cadangan perlu dilakukan pada perangkat serta konfigurasi yang benar-benar akan dipakai.</p>`;}
actions['package-add']=()=>{const form=dialog.querySelector('[data-form="settings"]');if(!form)return;const indices=[...form.querySelectorAll('[data-package-index]')].map(x=>+x.dataset.packageIndex);const i=Math.max(-1,...indices)+1;form.querySelector('#package-add-target').insertAdjacentHTML('beforebegin',`<div class="package-setting" data-package-index="${i}">${field('Paket','packageName'+i,'text','','required maxlength="40"')}${field('Rp / kg','packagePrice'+i,'number','','min="1" max="1000000" required')}${field('Target jam','packageHours'+i,'number',48,'min="1" max="240" required')}${btn('Hapus','package-remove',String(i),'text-btn danger')}</div>`);};
actions['package-remove']=id=>{const form=dialog.querySelector('[data-form="settings"]');if(form.querySelectorAll('[data-package-index]').length<=1)throw Error('Pertahankan minimal satu paket layanan.');form.querySelector('[data-package-index="'+Number(id)+'"]').remove();};
actions.readiness=async()=>{ownerOnly();closeModal();info=await THCloud.api('readiness',undefined,'GET');openModal('Kesiapan usaha',body(),true);};
actions['ready-team']=()=>{closeModal();ui.page='team';ui.tab='members';render();};
actions['ready-policies']=()=>{closeModal();ui.page='finance';THFinance.state.tab='settings';render();};
actions['ready-members']=()=>{closeModal();return THAccess.manage();};
document.addEventListener('change',async e=>{const t=e.target;if(!t.dataset.readyCheck)return;const before=!t.checked;t.disabled=true;try{await THCloud.mutate('readiness',{check:t.dataset.readyCheck,confirmed:t.checked});info=await THCloud.api('readiness',undefined,'GET');openModal('Kesiapan usaha',body(),true);}catch(err){t.checked=before;t.disabled=false;toast(err.message);}});
const original=render;render=function(){original();if(!window.THCloud?.state)return;const bottom=document.querySelector('.sidebar-bottom');if(bottom&&THCloud.state.member.role==='Owner')bottom.insertAdjacentHTML('afterbegin',btn('Kesiapan usaha','readiness','','nav-item','shield'));THCloud.paintStatus();};
})();
